/**
 * Calculate the late fee for an invoice.
 * @param {{ dueDate?: string, status: string, payments?: Array, lines: Array, voucher?: object }} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} Late fee in cents
 */
export function lateFee(invoice, asOf) {
  if (invoice.status === 'draft') return 0;
  if (!invoice.dueDate || invoice.dueDate >= asOf) return 0;

  const due = balanceDue(invoice);
  if (due <= 0) return 0;

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  return Math.max(0, roundCents((due * daysOverdue * 0.04) / 100));
}

/**
 * Generate a dashboard summary of invoices.
 * @param {Array<{ status: string, customerId: string, payments?: Array, lines: Array, voucher?: object }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: invoices.filter((inv) => inv.status === 'draft').length,
    issued: invoices.filter((inv) => inv.status === 'issued').length,
    partially_paid: invoices.filter((inv) => inv.status === 'partially_paid').length,
    paid: invoices.filter((inv) => inv.status === 'paid').length,
  };

  const outstanding = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .reduce((sum, inv) => sum + balanceDue(inv), 0);

  const overdue = overdueInvoices(invoices, asOf);
  const overdueAmount = overdue.reduce((sum, item) => sum + item.due, 0);

  const customerDues = {};
  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .forEach((inv) => {
      const customerId = inv.customerId;
      const due = balanceDue(inv);
      customerDues[customerId] = (customerDues[customerId] ?? 0) + due;
    });

  const topCustomers = Object.entries(customerDues)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: { count: overdue.length, amount: overdueAmount },
    topCustomers,
  };
}

